function cleanText(text, o){
  o=o||{};
  var eol = o.eol==='crlf' ? '\r\n' : (o.eol==='cr' ? '\r' : '\n');
  var lines = text.split(/\r\n|\r|\n/);
  if(o.tabsToSpaces){ var sp=''; for(var t=0;t<(o.tabSize||2);t++) sp+=' '; lines=lines.map(function(l){return l.replace(/\t/g,sp);}); }
  if(o.trimTail) lines = lines.map(function(l){return l.replace(/[ \t]+$/,'')});
  if(o.dropEmpty) lines = lines.filter(function(l){return l.replace(/\s/g,'').length>0;});
  if(o.collapse){ var r=[],pe=false; for(var i=0;i<lines.length;i++){var e=lines[i].replace(/\s/g,'').length===0; if(e&&pe)continue; r.push(lines[i]); pe=e;} lines=r; }
  if(o.dedup){ var seen={},r2=[]; for(var j=0;j<lines.length;j++){var k=lines[j]; if(o.dedupCI)k=k.toLowerCase(); if(seen[k])continue; seen[k]=1; r2.push(lines[j]);} lines=r2; }
  var out=lines.join(eol);
  if(o.noFinalNewline) out=out.replace(/\n+$/,'');
  return out;
}
var EXPORTS={cleanText:cleanText};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
